"""Friendly spreadsheet-style renderer for the data-management demo."""

from __future__ import annotations

import json
from typing import Any


def render_data_admin(state: dict[str, Any]) -> str:
    initial_state = json.dumps(state, ensure_ascii=False).replace("<", "\\u003c")
    page = """<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ERGOLIFE 数据工作台</title>
<style>
:root{--blue:#3370ff;--ink:#182230;--muted:#667085;--line:#e5eaf2;--bg:#f4f7fb;--green:#087443;--orange:#b54708;--red:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1400px;margin:auto;padding:26px 18px 60px}h1{margin:0;font-size:27px}h2{margin:0 0 12px;font-size:18px}.sub{color:var(--muted);margin:5px 0 16px}.top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;flex-wrap:wrap}.back{color:var(--blue);text-decoration:none;background:#fff;border:1px solid var(--line);border-radius:9px;padding:8px 12px}.notice{background:#fff9ed;border:1px solid #f5d08a;border-radius:12px;padding:12px 14px;color:#7a4b00;margin:16px 0}.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;margin:14px 0;box-shadow:0 3px 14px #1b3a5d08;overflow:auto}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.tab{border:1px solid var(--line);background:#fff;border-radius:9px;padding:9px 13px;cursor:pointer;color:var(--ink)}.tab.active{background:#edf3ff;border-color:#9dbaff;color:var(--blue);font-weight:700}.tab small{color:var(--muted);font-weight:400}.grid-toolbar{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:10px 0}.grid-toolbar input{width:240px}.grid-toolbar button,.grid-toolbar input{font:inherit;border:1px solid #cfd7e5;border-radius:8px;padding:8px;background:#fff;color:var(--ink)}button{cursor:pointer}.grid-toolbar button.primary,.confirm{background:var(--blue);border-color:var(--blue);color:#fff;font-weight:700}.count{margin-left:auto;color:var(--muted);font-size:12px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:820px}th,td{padding:8px 10px;border-bottom:1px solid #f0f2f6;text-align:left;white-space:nowrap;vertical-align:middle}th{background:#f8fafc;color:var(--muted);font-weight:600}tr:last-child td{border-bottom:0}td input,td select{width:100%;min-width:90px;padding:7px 8px;border:1px solid transparent;border-radius:6px;background:transparent;font:inherit;color:var(--ink)}td input:hover,td input:focus,td select:hover,td select:focus{border-color:#b5c7f8;background:#fff;outline:none}td .readonly{color:#667085;background:#f7f8fa;padding:7px 8px;border-radius:6px;display:inline-block}.dirty td{background:#f7faff}.new-row td{background:#f6fff9}.derived{color:#667085}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}.row-action{color:var(--red);border:0;background:transparent;font-size:12px}.empty{color:var(--muted);padding:28px;text-align:center}.hint{font-size:12px;color:var(--muted);margin:8px 0}.preview{display:none}.preview.show{display:block}.summary{display:flex;gap:22px;flex-wrap:wrap;background:#f8fafc;border-radius:10px;padding:12px 14px;margin-bottom:12px}.summary strong{font-size:20px;color:var(--blue);display:block}.summary small{color:var(--muted)}.change-row.user{background:#f4f8ff}.change-row.cascade{background:#fffaf0}.badge{display:inline-block;border-radius:99px;padding:3px 8px;font-size:11px;font-weight:700}.badge.user{background:#e0eaff;color:var(--blue)}.badge.cascade{background:#fff0c2;color:var(--orange)}.badge.delete{background:#fee4e2;color:var(--red)}.diff{white-space:pre-wrap;max-width:620px;word-break:break-word;color:#475467;font-size:12px}.success{color:var(--green);font-weight:700}.error{color:var(--red);font-weight:700}.legend{font-size:12px;color:var(--muted);margin-top:10px}.legend span{margin-right:15px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}.dot.user{background:var(--blue)}.dot.cascade{background:#f79009}@media(max-width:780px){.wrap{padding:20px 12px 45px}h1{font-size:23px}.count{margin-left:0}.grid-toolbar input{width:100%}.panel{padding:14px}}
</style></head><body><main class="wrap">
<div class="top"><div><h1>ERGOLIFE 数据工作台</h1><div class="sub">像操作表格一样维护业务数据，提交前先查看全部关联影响</div></div><a class="back" href="/dashboard">返回商品工作台</a></div>
<div class="notice">当前是体验版：暂不接真实数据库，暂不做权限。灰色字段由系统计算，普通员工只需要修改可编辑的白色单元格。</div>
<section class="panel"><h2 id="table-title">数据表</h2><div id="tabs" class="tabs"></div><div class="grid-toolbar"><input id="search" placeholder="搜索 SKU、商品名称或记录"><button id="add-row">＋ 添加一行</button><button id="preview-btn" class="primary" disabled>查看影响（0）</button><button id="reset-btn">恢复演示数据</button><span id="count" class="count"></span><span id="message"></span></div><div id="table-view"></div><div class="legend"><span><i class="dot user"></i>待提交的直接修改</span><span><i class="dot cascade"></i>确认后系统自动连锁更新</span></div></section>
<section id="preview-panel" class="panel preview"><h2>提交前影响确认</h2><div id="preview-summary" class="summary"></div><div class="hint">下面列出本次操作会影响的每一条业务记录。确认后才会统一提交。</div><div class="table-wrap"><table><thead><tr><th>来源</th><th>数据表</th><th>记录</th><th>变化类型</th><th>具体变化</th></tr></thead><tbody id="changes"></tbody></table></div><div class="grid-toolbar"><button id="commit-btn" class="confirm">确认并提交全部变更</button><button id="cancel-btn">返回继续编辑</button></div></section>
</main><script>
const initialState=__INITIAL_STATE__;let state=initialState;let currentTable='sales_daily';let drafts=[];let insertDrafts=[];let deleteDrafts=[];let pendingPreview=null;const meta=state.metadata;const tables=Object.keys(meta);const numberFields=new Set(['units','on_hand','reserved','damaged','safety_stock']);
const esc=(value)=>String(value??'').replace(/[&<>"']/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));const productLabel=(id)=>{const product=(state.tables.products||[]).find((row)=>row.id===id);return product?product.sku+' · '+product.product_name:String(id??'—')};const displayValue=(field,value)=>field==='product_id'?productLabel(value):String(value??'—');const typeValue=(field,value)=>numberFields.has(field)?Number(value):String(value??'');
function currentDraft(table,id){return drafts.find((draft)=>draft.table===table&&draft.record_id===id)}function isDeleted(table,id){return deleteDrafts.some((draft)=>draft.table===table&&draft.record_id===id)}function originalValue(table,id,field){const row=(state.tables[table]||[]).find((item)=>item.id===id);return row?row[field]:undefined}
function updateDraftCell(table,id,field,value){let draft=currentDraft(table,id);if(!draft){draft={table,operation:'update',record_id:id,values:{}};drafts.push(draft)}if(typeValue(field,value)===typeValue(field,originalValue(table,id,field)))delete draft.values[field];else draft.values[field]=typeValue(field,value);if(!Object.keys(draft.values).length)drafts=drafts.filter((item)=>item!==draft)}function queueCell(table,id,field,value){updateDraftCell(table,id,field,value);renderGrid();updatePreviewButton()}
function queueInsert(tempId,field,value){const draft=insertDrafts.find((item)=>item.temp_id===tempId);if(draft)draft.values[field]=typeValue(field,value);updatePreviewButton()}
function productOptions(value){return (state.tables.products||[]).map((row)=>'<option value="'+esc(row.id)+'" '+(row.id===value?'selected':'')+'>'+esc(row.sku+' · '+row.product_name)+'</option>').join('')}
function editableCell(table,row,field,isNew){const editable=meta[table].editable_fields.includes(field);const value=row[field];if(!editable)return '<span class="readonly '+(meta[table].column_labels[field].includes('计算')?'derived':'')+'">'+esc(displayValue(field,value))+'</span>';if(field==='product_id')return '<select data-field="'+field+'" data-id="'+esc(isNew?row.temp_id:row.id)+'" data-new="'+isNew+'">'+productOptions(value)+'</select>';if(field==='status')return '<select data-field="status" data-id="'+esc(isNew?row.temp_id:row.id)+'" data-new="'+isNew+'"><option value="active" '+(value==='active'?'selected':'')+'>启用</option><option value="inactive" '+(value==='inactive'?'selected':'')+'>停用</option></select>';return '<input data-field="'+field+'" data-id="'+esc(isNew?row.temp_id:row.id)+'" data-new="'+isNew+'" type="'+(field==='sale_date'?'date':numberFields.has(field)?'number':'text')+'" value="'+esc(value)+'">'}
function renderGrid(){const definition=meta[currentTable];const columns=definition.columns.filter((field)=>field!=='id');const query=document.getElementById('search').value.trim().toLowerCase();const rows=(state.tables[currentTable]||[]).filter((row)=>!isDeleted(currentTable,row.id)).filter((row)=>!query||JSON.stringify(row).toLowerCase().includes(query)||displayValue('product_id',row.product_id).toLowerCase().includes(query));const newRows=insertDrafts.filter((draft)=>draft.table===currentTable).map((draft)=>({...draft.values,temp_id:draft.temp_id}));const head=columns.map((field)=>'<th>'+esc(definition.column_labels[field]||field)+'</th>').join('')+'<th>操作</th>';const body=rows.map((row)=>{const dirty=currentDraft(currentTable,row.id);const editRow={...row,...(dirty?dirty.values:{})};return '<tr class="'+(dirty?'dirty':'')+'">'+columns.map((field)=>'<td>'+editableCell(currentTable,editRow,field,false)+'</td>').join('')+'<td><button class="row-action" data-delete-id="'+esc(row.id)+'">删除</button></td></tr>'}).join('')+newRows.map((row)=>'<tr class="new-row">'+columns.map((field)=>'<td>'+editableCell(currentTable,row,field,true)+'</td>').join('')+'<td><button class="row-action" data-new-delete="'+esc(row.temp_id)+'">取消</button></td></tr>').join('');document.getElementById('table-title').textContent=definition.label;document.getElementById('table-view').innerHTML=body?'<div class="table-wrap"><table><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table></div>':'<div class="empty">暂无记录，可以点击“＋ 添加一行”</div>';document.getElementById('count').textContent=rows.length+' 条记录'+(newRows.length?' · 新增 '+newRows.length:'')}
function renderTabs(){document.getElementById('tabs').innerHTML=tables.map((table)=>'<button class="tab '+(table===currentTable?'active':'')+'" data-table="'+table+'">'+esc(meta[table].label)+'<small> · '+(state.tables[table]||[]).length+' 条</small></button>').join('');document.querySelectorAll('[data-table]').forEach((button)=>button.addEventListener('click',()=>{currentTable=button.dataset.table;renderTabs();renderGrid()}))}
function setState(next){state=next;drafts=[];insertDrafts=[];deleteDrafts=[];pendingPreview=null;document.getElementById('preview-panel').classList.remove('show');renderTabs();renderGrid();updatePreviewButton()}
function operations(){return [...drafts,...insertDrafts.map((draft)=>({table:draft.table,operation:'insert',record_id:'',values:draft.values})),...deleteDrafts.map((draft)=>({table:draft.table,operation:'delete',record_id:draft.record_id,values:{}}))]}
function updatePreviewButton(){const count=operations().length;const button=document.getElementById('preview-btn');button.disabled=!count;button.textContent='查看影响（'+count+'）'}
async function send(url,options){const response=await fetch(url,options);const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.detail||'请求失败');return body}
function diffText(change){if(!change.before)return '新增：'+Object.entries(change.after||{}).filter(([key])=>key!=='id').map(([key,value])=>(meta[change.table].column_labels[key]||key)+'：'+displayValue(key,value)).join('；');if(!change.after)return '删除：'+displayValue('product_id',change.before.product_id||change.before.id);const keys=[...new Set([...Object.keys(change.before),...Object.keys(change.after)])];return keys.filter((key)=>change.before[key]!==change.after[key]).map((key)=>(meta[change.table].column_labels[key]||key)+'：'+displayValue(key,change.before[key])+' → '+displayValue(key,change.after[key])).join('；')||'字段重新计算'}
function renderPreview(preview){pendingPreview=preview;document.getElementById('preview-panel').classList.add('show');const summary=preview.summary;document.getElementById('preview-summary').innerHTML='<div><strong>'+summary.total+'</strong><small>总影响记录</small></div><div><strong>'+summary.user_changes+'</strong><small>你的修改</small></div><div><strong>'+summary.cascade_changes+'</strong><small>系统连锁更新</small></div><div><strong>'+summary.deletes+'</strong><small>删除记录</small></div>';document.getElementById('changes').innerHTML=preview.changes.map((change)=>'<tr class="change-row '+(change.source==='用户操作'?'user':'cascade')+'"><td><span class="badge '+(change.source==='用户操作'?'user':'cascade')+'">'+esc(change.source)+'</span></td><td>'+esc(change.table_label)+'</td><td class="mono">'+esc(change.record_id)+'</td><td><span class="badge '+(change.change_type==='delete'?'delete':'')+'">'+({insert:'新增',update:'修改',delete:'删除'}[change.change_type]||change.change_type)+'</span></td><td><div class="diff">'+esc(diffText(change))+'</div></td></tr>').join('')}
document.getElementById('search').addEventListener('input',renderGrid);document.getElementById('add-row').addEventListener('click',()=>{const defaults=currentTable==='sales_daily'?{product_id:'prod-70030',sale_date:'2026-08-31',units:0}:currentTable==='inventory_positions'?{product_id:'prod-70030',warehouse:'US-02',on_hand:0,reserved:0,damaged:0}:currentTable==='products'?{sku:'',product_name:'',status:'active'}:{product_id:'prod-70030',safety_stock:0};insertDrafts.push({table:currentTable,temp_id:'new-'+Date.now()+'-'+Math.random().toString(16).slice(2),values:defaults});renderGrid();updatePreviewButton()});document.getElementById('table-view').addEventListener('input',(event)=>{const target=event.target;if(!target.dataset.field)return;if(target.dataset.new==='true')queueInsert(target.dataset.id,target.dataset.field,target.value);else{updateDraftCell(currentTable,target.dataset.id,target.dataset.field,target.value);updatePreviewButton()}});document.getElementById('table-view').addEventListener('change',(event)=>{const target=event.target;if(!target.dataset.field)return;if(target.dataset.new==='true')queueInsert(target.dataset.id,target.dataset.field,target.value);else queueCell(currentTable,target.dataset.id,target.dataset.field,target.value)});document.getElementById('table-view').addEventListener('click',(event)=>{const id=event.target.dataset.deleteId;const temp=event.target.dataset.newDelete;if(id){drafts=drafts.filter((draft)=>!(draft.table===currentTable&&draft.record_id===id));if(!isDeleted(currentTable,id))deleteDrafts.push({table:currentTable,record_id:id});renderGrid();updatePreviewButton()}if(temp){insertDrafts=insertDrafts.filter((draft)=>draft.temp_id!==temp);renderGrid();updatePreviewButton()}});document.getElementById('preview-btn').addEventListener('click',async()=>{try{const preview=await send('/api/data-admin/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operations:operations()})});renderPreview(preview)}catch(error){showMessage(error.message,true)}});document.getElementById('commit-btn').addEventListener('click',async()=>{if(!pendingPreview)return;try{const result=await send('/api/data-admin/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({preview_id:pendingPreview.preview_id})});setState(result.state);showMessage('已确认提交，数据已更新',false)}catch(error){showMessage(error.message,true)}});document.getElementById('cancel-btn').addEventListener('click',()=>{pendingPreview=null;document.getElementById('preview-panel').classList.remove('show')});document.getElementById('reset-btn').addEventListener('click',async()=>{try{const result=await send('/api/data-admin/reset',{method:'POST'});setState(result);showMessage('演示数据已恢复',false)}catch(error){showMessage(error.message,true)}});function showMessage(message,isError){const node=document.getElementById('message');node.textContent=message;node.className=isError?'error':'success'}renderTabs();renderGrid();updatePreviewButton();
</script></body></html>"""
    return page.replace("__INITIAL_STATE__", initial_state)
